BEGIN;
CREATE TYPE provider_status AS ENUM ('DRAFT','PENDING','APPROVED','REJECTED','SUSPENDED');
CREATE TYPE program_status AS ENUM ('DRAFT','PUBLISHED','SUSPENDED');
CREATE TYPE booking_status AS ENUM ('CONFIRMED','CANCELLED','COMPLETED','SESSION_CANCELLED');
CREATE TABLE users (id text PRIMARY KEY,email text NOT NULL UNIQUE CHECK(email=lower(email)),password_hash text NOT NULL,display_name text NOT NULL,birth_date date NOT NULL,prefecture text NOT NULL DEFAULT '',city text NOT NULL DEFAULT '',email_verified boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),deleted_at timestamptz);
CREATE TABLE user_roles (user_id text REFERENCES users(id),role text NOT NULL CHECK(role IN ('USER','GUARDIAN','PROVIDER','ADMIN')),PRIMARY KEY(user_id,role));
CREATE TABLE participant_profiles (id text PRIMARY KEY,owner_id text NOT NULL REFERENCES users(id),display_name text NOT NULL,birth_date date NOT NULL,prefecture text NOT NULL DEFAULT '',city text NOT NULL DEFAULT '',kind text NOT NULL CHECK(kind IN ('SELF','CHILD')),created_at timestamptz NOT NULL DEFAULT now(),deleted_at timestamptz);
CREATE TABLE guardian_profiles (user_id text PRIMARY KEY REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE participant_interests (participant_id text REFERENCES participant_profiles(id),category_id text NOT NULL,PRIMARY KEY(participant_id,category_id));
CREATE TABLE categories (id text PRIMARY KEY,name text NOT NULL UNIQUE);
CREATE TABLE providers (id text PRIMARY KEY,owner_id text NOT NULL REFERENCES users(id),kind text NOT NULL,name text NOT NULL,bio text NOT NULL,prefecture text NOT NULL,city text NOT NULL,contact text NOT NULL,experience text NOT NULL DEFAULT '',qualifications text NOT NULL DEFAULT '',status provider_status NOT NULL DEFAULT 'DRAFT',created_at timestamptz NOT NULL DEFAULT now(),deleted_at timestamptz);
CREATE TABLE provider_categories (provider_id text REFERENCES providers(id),category_id text REFERENCES categories(id),PRIMARY KEY(provider_id,category_id));
CREATE TABLE provider_documents (id text PRIMARY KEY,provider_id text NOT NULL REFERENCES providers(id),owner_id text NOT NULL REFERENCES users(id),private_key text NOT NULL UNIQUE,original_name text NOT NULL,content_type text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE provider_review_history (id text PRIMARY KEY,provider_id text NOT NULL REFERENCES providers(id),actor_id text NOT NULL REFERENCES users(id),from_status provider_status NOT NULL,to_status provider_status NOT NULL,comment text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE programs (id text PRIMARY KEY,provider_id text NOT NULL REFERENCES providers(id),title text NOT NULL,category_id text NOT NULL REFERENCES categories(id),description text NOT NULL,image_url text NOT NULL,min_age integer NOT NULL CHECK(min_age>=0),max_age integer NOT NULL CHECK(max_age>=min_age),difficulty text NOT NULL,coin_cost integer NOT NULL CHECK(coin_cost>=1),prefecture text NOT NULL,city text NOT NULL,location text NOT NULL,belongings text NOT NULL DEFAULT '',notes text NOT NULL DEFAULT '',status program_status NOT NULL DEFAULT 'DRAFT',rating numeric(3,2) NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now(),deleted_at timestamptz);
CREATE TABLE program_images (id text PRIMARY KEY,program_id text NOT NULL REFERENCES programs(id),object_key text NOT NULL,sort_order integer NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE session_slots (id text PRIMARY KEY,program_id text NOT NULL REFERENCES programs(id),starts_at timestamptz NOT NULL,ends_at timestamptz NOT NULL,capacity integer NOT NULL CHECK(capacity>=0),booking_deadline timestamptz NOT NULL,location text NOT NULL,cancelled boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),CHECK(ends_at>starts_at),CHECK(booking_deadline<=starts_at));
CREATE TABLE bookings (id text PRIMARY KEY,number text NOT NULL UNIQUE,user_id text NOT NULL REFERENCES users(id),participant_id text NOT NULL REFERENCES participant_profiles(id),slot_id text NOT NULL REFERENCES session_slots(id),coin_cost integer NOT NULL CHECK(coin_cost>=1),status booking_status NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),cancelled_at timestamptz,completed_at timestamptz);
CREATE UNIQUE INDEX bookings_active_participant_slot ON bookings(participant_id,slot_id) WHERE status='CONFIRMED';
CREATE TABLE booking_status_history (id text PRIMARY KEY,booking_id text NOT NULL REFERENCES bookings(id),actor_id text NOT NULL REFERENCES users(id),from_status booking_status,to_status booking_status NOT NULL,reason text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE coin_ledger_entries (id text PRIMARY KEY,wallet_user_id text NOT NULL REFERENCES users(id),entry_type text NOT NULL,amount integer NOT NULL,booking_id text REFERENCES bookings(id),payment_id text,provider_id text REFERENCES providers(id),reason text NOT NULL,reversal_of_id text REFERENCES coin_ledger_entries(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE wallets (user_id text PRIMARY KEY REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE payment_transactions (id text PRIMARY KEY,user_id text NOT NULL REFERENCES users(id),provider_payment_id text NOT NULL UNIQUE,coins integer NOT NULL CHECK(coins>=1),status text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE webhook_events (id text PRIMARY KEY,provider_event_id text NOT NULL UNIQUE,payload_hash text NOT NULL,processed_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE provider_earnings (id text PRIMARY KEY,provider_id text NOT NULL REFERENCES providers(id),booking_id text NOT NULL UNIQUE REFERENCES bookings(id),gross_coins integer NOT NULL,fee_coins integer NOT NULL,net_coins integer NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE reviews (id text PRIMARY KEY,booking_id text NOT NULL UNIQUE REFERENCES bookings(id),user_id text NOT NULL REFERENCES users(id),program_id text NOT NULL REFERENCES programs(id),rating integer NOT NULL CHECK(rating BETWEEN 1 AND 5),comment text NOT NULL,visible boolean NOT NULL DEFAULT true,reported boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE review_reports (id text PRIMARY KEY,review_id text NOT NULL REFERENCES reviews(id),reporter_id text NOT NULL REFERENCES users(id),reason text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE notifications (id text PRIMARY KEY,user_id text NOT NULL REFERENCES users(id),type text NOT NULL,message text NOT NULL,read boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE service_settings (singleton boolean PRIMARY KEY DEFAULT true CHECK(singleton),fee_percent integer NOT NULL DEFAULT 10 CHECK(fee_percent BETWEEN 0 AND 100),app_name text NOT NULL DEFAULT 'ClubConnect');
CREATE TABLE audit_logs (id text PRIMARY KEY,actor_id text NOT NULL REFERENCES users(id),action text NOT NULL,target_type text NOT NULL,target_id text NOT NULL,summary text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE auth_sessions (id text PRIMARY KEY,user_id text NOT NULL REFERENCES users(id),csrf_token text NOT NULL,expires_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE FUNCTION reject_ledger_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'coin ledger entries are append-only'; END $$;
CREATE TRIGGER coin_ledger_immutable BEFORE UPDATE OR DELETE ON coin_ledger_entries FOR EACH ROW EXECUTE FUNCTION reject_ledger_mutation();
CREATE INDEX programs_search ON programs(status,category_id,prefecture,city,coin_cost);
CREATE INDEX slots_search ON session_slots(program_id,starts_at,booking_deadline) WHERE cancelled=false;
CREATE INDEX ledger_wallet_time ON coin_ledger_entries(wallet_user_id,created_at DESC);
CREATE INDEX audit_time ON audit_logs(created_at DESC);
INSERT INTO service_settings(singleton) VALUES(true);
COMMIT;
